//! OUTPUT form content attributes drive genuine native association.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner></form><form id=other></form><label id=label for=output>Result</label><output id=output form=owner for=seed name=result>default</output><div id=mount></div></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://output-form-attribute.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn output_form_attribute_public_scalar_writes_change_actual_owner_and_label_form(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var output=document.getElementById('output'),owner=document.getElementById('owner'),other=document.getElementById('other'),label=document.getElementById('label'),labels=output.labels,tokens=output.htmlFor,attr=output.getAttributeNode('form');output.setAttribute('form','other');if(output.form!==other||label.form!==other||output.labels!==labels||labels[0]!==label||output.htmlFor!==tokens||tokens.value!=='seed'||output.name!=='result'||output.getAttributeNode('form')!==attr||attr.value!=='other')throw 'actual form attribute association';output.setAttribute('form','missing');if(output.form!==null||label.form!==null)throw 'explicit owner miss';output.removeAttribute('form');owner.appendChild(output);if(output.form!==owner||label.form!==owner)throw 'ancestor association recovery';");}
#[test]
fn output_form_attribute_exact_utf16_public_and_null_namespace_producers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),owner=document.getElementById('owner'),other=document.getElementById('other'),label=document.getElementById('label');owner.id='A\ud800z';other.id='A\udfffz';output.setAttribute('form','A\ud800z');var attr=output.getAttributeNode('form');if(output.getAttribute('form')!=='A\ud800z'||attr.value!=='A\ud800z'||output.form!==owner||label.form!==owner)throw 'exact public form owner';output.setAttributeNS(null,'form','A\udfffz');if(output.form!==other||label.form!==other||output.getAttributeNode('form')!==attr||attr.value!=='A\udfffz'||document.querySelector('[form="A�z"]')!==null)throw 'null namespace raw alias owner';output.setAttribute('form','A�z');if(output.form!==null||label.form!==null)throw 'scalar alias is distinct';"#);}
#[test]
fn output_form_attribute_attached_aliases_conversion_reentry_and_observer_old_values(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),owner=document.getElementById('owner'),other=document.getElementById('other'),attr=output.getAttributeNode('form'),watch=new MutationObserver(function(){}),calls=0;watch.observe(output,{attributes:true,attributeOldValue:true});output.setAttribute('form','other');attr.value='owner';var records=watch.takeRecords();if(records.length!==2||records[0].oldValue!=='owner'||records[1].oldValue!=='other'||output.form!==owner||output.getAttributeNode('form')!==attr)throw 'native Attr association and records';owner.id='A\ud800z';other.id='A\udfffz';attr.nodeValue='A\ud800z';attr.textContent='A\udfffz';records=watch.takeRecords();if(records.length!==2||records[0].oldValue!=='owner'||records[1].oldValue!=='A\ud800z'||attr.value!=='A\udfffz'||output.form!==other)throw 'exact attached aliases';output.setAttribute('form',{toString:function(){calls++;attr.value='A\ud800z';return 'A\udfffz';}});records=watch.takeRecords();if(calls!==1||records.length!==2||records[0].oldValue!=='A\udfffz'||records[1].oldValue!=='A\ud800z'||output.form!==other||attr.ownerElement!==output)throw 'current native association after conversion';"#);}

#[test]
fn output_form_attribute_conversion_reentry_replaces_actual_attr_and_keeps_abrupt_effects(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),old=output.getAttributeNode('form'),calls=0;output.setAttribute('form',{toString:function(){calls++;output.removeAttribute('form');output.setAttribute('form','callback');return 'A\ud800z';}});var actual=output.getAttributeNode('form');if(calls!==1||actual===old||old.ownerElement!==null||old.value!=='owner'||actual.value!=='A\ud800z')throw 'conversion uses current actual attribute';var marker={},caught;try{output.setAttribute('form',{toString:function(){output.setAttribute('form','abrupt callback');throw marker;}});}catch(e){caught=e;}if(caught!==marker||output.getAttribute('form')!=='abrupt callback'||output.getAttributeNode('form')!==actual)throw 'abrupt conversion keeps completed author effects';caught=false;try{output.setAttribute('form',Symbol('form'));}catch(e){caught=e instanceof TypeError;}if(!caught||actual.value!=='abrupt callback')throw 'symbol conversion refusal';"#);}

#[test]
fn output_form_attribute_inert_clone_adoption_no_main_slots_and_whole_import_guard(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('output');source.setAttribute('form','A\ud800z B\udfffz');var copy=source.cloneNode(true),a=copy.getAttributeNode('form'),target=document.implementation.createHTMLDocument('target');target.adoptNode(copy);target.body.appendChild(copy);if(copy.getAttribute('form')!==source.getAttribute('form')||a===source.getAttributeNode('form')||copy.ownerDocument!==target||a.ownerDocument!==target)throw 'independent clone and actual adopted attributes';source.setAttribute('form','fresh');if(a.value!=='A\ud800z B\udfffz')throw 'independent copied record';"#);let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();let error=p.runtime.execute("document.importNode(copy,true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("Import supports ordinary HTML containers"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);let slots=d.nodes.len();p.state.node_limit=slots;p.begin_job();run(&mut d,&mut f,&mut p,r#"var isolated=owner.createElement('output');isolated.setAttribute('form','X\ud800');var attr=isolated.getAttributeNode('form');attr.value='Y\udfff';if(isolated.getAttribute('form')!=='Y\udfff'||attr.ownerDocument!==owner||a.value!=='A\ud800z B\udfffz')throw 'fresh inert exact source without main slots';document.getElementById('output').setAttribute('form','Z\ud800');"#);assert_eq!(d.nodes.len(),slots);}

#[test]
fn output_form_attribute_qualified_foreign_and_other_element_guards_are_atomic(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var output=document.getElementById('output'),other=document.createElement('div'),shape=document.createElementNS('http://www.w3.org/2000/svg','svg');");let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());for source in [r#"output.setAttributeNS('urn:attribute','form','A\ud800');"#,r#"output.setAttributeNS(null,'FORM','A\ud800');"#,r#"other.setAttribute('form','A\ud800');"#,r#"shape.setAttribute('form','A\ud800');"#]{p.begin_job();assert!(p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err(),"{source}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);}p.begin_job();run(&mut d,&mut f,&mut p,r#"output.setAttribute('form','B\udfff');if(output.getAttribute('form')!=='B\udfff')throw 'fresh exact native write recovery';"#);}

#[test]
fn output_form_attribute_saved_child_origin_precedes_author_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var saved=frame.contentWindow.Function('node','value',"node.setAttribute('form',value);"),calls=0;saved(output,'A\ud800z');"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.set_location(&crate::navigation::address("https://other-output-for.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("saved(output,{toString:function(){calls++;return 'bad';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.set_location(&crate::navigation::address("https://output-form-attribute.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,r#"if(calls||output.getAttribute('form')!=='A\ud800z')throw 'origin before conversion';saved(output,'B\udfffz');if(output.getAttribute('form')!=='B\udfffz')throw 'fresh captured origin recovery';"#);}

#[test]
fn output_form_attribute_null_namespace_writes_ignore_foreign_collision_after_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output');output.setAttributeNS('urn:attribute','form','foreign');var foreign=output.getAttributeNodeNS('urn:attribute','form'),a=output.getAttributeNodeNS(null,'form'),calls=0;output.setAttributeNS(null,'form',{toString:function(){calls++;output.setAttributeNS(null,'form','callback');return 'A\ud800z';}});if(calls!==1||output.getAttributeNodeNS(null,'form')!==a||a.value!=='A\ud800z'||foreign!==output.getAttributeNodeNS('urn:attribute','form')||foreign.value!=='foreign'||output.getAttributeNS(null,'form')!=='A\ud800z')throw 'exact converted null namespace output attribute';"#);}

#[test]
fn output_form_attribute_native_and_inert_writer_limits_preserve_records_and_recover(){for inert in [false,true]{for source in [r#"output.setAttribute('form','long A\ud800z B\udfffz');"#,r#"output.setAttributeNS(null,'form','long A\ud800z B\udfffz');"#,r#"attr.value='long A\ud800z B\udfffz';"#]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var doc=document.implementation.createHTMLDocument('inert'),output=doc.createElement('output');output.setAttribute('form','owner');var attr=output.getAttributeNode('form'),watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});"}else{"var output=document.getElementById('output'),attr=output.getAttributeNode('form'),watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});"});p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone(),p.state.output_defaults.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone(),p.state.output_defaults.len()),state);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='owner'||output.getAttributeNode('form')!==attr||watch.takeRecords().length)throw 'atomic form writer refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,r#"var records=watch.takeRecords();if(attr.value!=='long A\ud800z B\udfffz'||output.getAttributeNode('form')!==attr||records.length!==1||records[0].oldValue!=='owner'||records[0].attributeName!=='form'||records[0].attributeNamespace!==null||output.form!==null)throw 'fresh writer recovery';"#);}}}}
#[test]
fn output_form_attribute_native_reset_uses_attribute_authority_and_ignores_form_shadow(){let(mut d,mut f,mut p)=fixture();let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("owner")).unwrap();let other=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("other")).unwrap();run(&mut d,&mut f,&mut p,"var output=document.getElementById('output'),owner=document.getElementById('owner'),other=document.getElementById('other'),getter=Object.getOwnPropertyDescriptor(HTMLOutputElement.prototype,'form').get;output.value='current';Object.defineProperty(output,'form',{value:owner,configurable:true});output.setAttribute('form','other');if(getter.call(output)!==other||document.getElementById('label').form!==other||output.form!==owner)throw 'native attribute authority';");p.begin_job();reset_form(&mut d,&mut f,Some(&mut p),owner).unwrap();run(&mut d,&mut f,&mut p,"if(output.value!=='current'||output.defaultValue!=='default')throw 'wrong owner reset';");p.begin_job();reset_form(&mut d,&mut f,Some(&mut p),other).unwrap();run(&mut d,&mut f,&mut p,"if(output.value!=='default'||output.defaultValue!==output.value)throw 'current actual owner reset';delete output.form;output.defaultValue='next';if(output.value!=='next'||output.form!==other)throw 'fresh output form recovery';");}

#[test]
fn output_form_attribute_html_casefold_and_widget_reassociation_boundary(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var output=document.getElementById('output'),other=document.getElementById('other'),owner=document.getElementById('owner');output.setAttribute('FORM','other');if(output.form!==other||output.getAttribute('form')!=='other'||output.getAttributeNodeNS(null,'FORM')!==null)throw 'HTML name normalization';var field=document.createElement('input');owner.appendChild(field);field.value='keep';");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text())).collect::<Vec<_>>();p.begin_job();let error=p.runtime.execute("field.setAttribute('form','other');",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("exclude"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text())).collect::<Vec<_>>(),controls);p.begin_job();run(&mut d,&mut f,&mut p,"if(field.form!==owner||field.value!=='keep'||output.form!==other)throw 'widget authority preserved';output.setAttribute('form','owner');if(output.form!==owner)throw 'fresh passive owner recovery';");}
